//! Parity of the preference-learning components of phase 10b with BoTorch
//! and scipy, from the fixtures in `tests/fixtures/10b_preference/*.json`
//! (generated by `scripts/generate_fixtures.py --phase 10b-preference`).
//!
//! * `hybrj_scipy.json`: MINPACK's `hybrj` (scipy's `fsolve` with `fprime`)
//!   on test systems whose values Rust and Python compute bitwise
//!   identically: the sequence of function and Jacobian evaluation points,
//!   the result and the counters must be scipy's bitwise.
//!
//! Run with `--nocapture` to print the error tables.

#![allow(clippy::needless_range_loop)]

mod common;

use std::cell::RefCell;

use botorch_core::minpack::fsolve;
use botorch_core::Matrix;
use common::fixture_dir;
use serde::Deserialize;

fn fixture_path(name: &str) -> std::path::PathBuf {
    fixture_dir().join("10b_preference").join(name)
}

// ---------------------------------------------------------------------------
// MINPACK hybrj against scipy's fsolve
// ---------------------------------------------------------------------------

#[derive(Deserialize)]
struct HybrjCase {
    x0: Vec<f64>,
    xtol: f64,
    maxfev: usize,
    /// scipy's calls: its two shape checks, a repeated evaluation at `x0`,
    /// then MINPACK's evaluations.
    calls: Vec<(String, Vec<f64>)>,
    x: Vec<f64>,
    ier: i32,
    nfev: usize,
    njev: usize,
}

type Sys = (fn(&[f64]) -> Vec<f64>, fn(&[f64]) -> Vec<Vec<f64>>);

fn rosen(x: &[f64]) -> Vec<f64> {
    vec![10.0 * (x[1] - x[0] * x[0]), 1.0 - x[0]]
}
fn rosen_j(x: &[f64]) -> Vec<Vec<f64>> {
    vec![vec![-20.0 * x[0], 10.0], vec![-1.0, 0.0]]
}
fn powell(x: &[f64]) -> Vec<f64> {
    let (s5, s10) = (5f64.sqrt(), 10f64.sqrt());
    let a = x[1] - 2.0 * x[2];
    let b = x[0] - x[3];
    vec![x[0] + 10.0 * x[1], s5 * (x[2] - x[3]), a * a, s10 * (b * b)]
}
fn powell_j(x: &[f64]) -> Vec<Vec<f64>> {
    let (s5, s10) = (5f64.sqrt(), 10f64.sqrt());
    let a = x[1] - 2.0 * x[2];
    let b = x[0] - x[3];
    vec![
        vec![1.0, 10.0, 0.0, 0.0],
        vec![0.0, 0.0, s5, -s5],
        vec![0.0, 2.0 * a, -4.0 * a, 0.0],
        vec![2.0 * s10 * b, 0.0, 0.0, -2.0 * s10 * b],
    ]
}
fn btri(x: &[f64]) -> Vec<f64> {
    let n = x.len();
    (0..n)
        .map(|i| {
            let xm = if i > 0 { x[i - 1] } else { 0.0 };
            let xp = if i < n - 1 { x[i + 1] } else { 0.0 };
            (3.0 - 2.0 * x[i]) * x[i] - xm - 2.0 * xp + 1.0
        })
        .collect()
}
fn btri_j(x: &[f64]) -> Vec<Vec<f64>> {
    let n = x.len();
    let mut j = vec![vec![0.0; n]; n];
    for i in 0..n {
        j[i][i] = 3.0 - 4.0 * x[i];
        if i > 0 {
            j[i][i - 1] = -1.0;
        }
        if i < n - 1 {
            j[i][i + 1] = -2.0;
        }
    }
    j
}
fn bband(x: &[f64]) -> Vec<f64> {
    let n = x.len();
    (0..n)
        .map(|i| {
            let mut s = 0.0;
            for j in i.saturating_sub(5)..(i + 2).min(n) {
                if j != i {
                    s += x[j] * (1.0 + x[j]);
                }
            }
            x[i] * (2.0 + 5.0 * x[i] * x[i]) + 1.0 - s
        })
        .collect()
}
fn bband_j(x: &[f64]) -> Vec<Vec<f64>> {
    let n = x.len();
    let mut jac = vec![vec![0.0; n]; n];
    for i in 0..n {
        for j in i.saturating_sub(5)..(i + 2).min(n) {
            if j != i {
                jac[i][j] = -(1.0 + 2.0 * x[j]);
            }
        }
        jac[i][i] = 2.0 + 15.0 * x[i] * x[i];
    }
    jac
}
fn noroot(x: &[f64]) -> Vec<f64> {
    vec![x[0] * x[0] + 1.0, x[1] - 2.0]
}
fn noroot_j(x: &[f64]) -> Vec<Vec<f64>> {
    vec![vec![2.0 * x[0], 0.0], vec![0.0, 1.0]]
}

fn system(name: &str) -> Sys {
    match name {
        "rosenbrock" | "rosenbrock_maxfev5" => (rosen, rosen_j),
        "powell_singular" => (powell, powell_j),
        "broyden_tridiagonal" => (btri, btri_j),
        "broyden_banded" => (bband, bband_j),
        "no_root" => (noroot, noroot_j),
        other => panic!("unknown hybrj system {other}"),
    }
}

#[test]
fn hybrj_reproduces_scipy_fsolve_bitwise() {
    let text = std::fs::read_to_string(fixture_path("hybrj_scipy.json")).unwrap();
    let cases: std::collections::BTreeMap<String, HybrjCase> = serde_json::from_str(&text).unwrap();
    assert!(cases.len() >= 6);
    for (name, case) in &cases {
        let (f, j) = system(name);
        let calls: RefCell<Vec<(String, Vec<f64>)>> = RefCell::new(Vec::new());
        let r = fsolve(
            |x| {
                calls.borrow_mut().push(("f".into(), x.to_vec()));
                Ok(f(x))
            },
            |x| {
                calls.borrow_mut().push(("j".into(), x.to_vec()));
                let rows = j(x);
                let n = rows.len();
                Ok(Matrix::from_fn(n, n, |a, b| rows[a][b]))
            },
            &case.x0,
            case.xtol,
            case.maxfev,
        )
        .unwrap();
        // scipy: shape checks of `func` and `fprime`, a second evaluation at
        // x0, then MINPACK's sequence (starting with its own f(x0)).
        let expected: Vec<(String, Vec<f64>)> = case.calls[3..].to_vec();
        let got = calls.into_inner();
        assert_eq!(got.len(), expected.len(), "{name}: number of calls");
        for (k, (g, e)) in got.iter().zip(&expected).enumerate() {
            assert_eq!(g.0, e.0, "{name}: kind of call {k}");
            assert_eq!(g.1, e.1, "{name}: point of call {k}");
        }
        assert_eq!(r.x, case.x, "{name}: solution");
        assert_eq!(r.info, case.ier, "{name}: info");
        // scipy's `nfev` counts its shape check and the repeated evaluation.
        assert_eq!(r.nfev + 2, case.nfev, "{name}: nfev");
        assert_eq!(r.njev, case.njev, "{name}: njev");
        println!(
            "hybrj {name:22} info={} nfev={} njev={} calls={}: bitwise equal",
            r.info,
            r.nfev,
            r.njev,
            got.len()
        );
    }
}

// ---------------------------------------------------------------------------
// PairwiseGP against BoTorch
// ---------------------------------------------------------------------------

use botorch_core::fit::FitOptions;
use botorch_core::kernels::CovarModule;
use botorch_core::models::likelihoods::PairwiseLikelihood;
use botorch_core::models::pairwise_gp::{LaplaceState, PairwiseGP, PairwiseGPOptions};
use botorch_core::models::Model;
use botorch_core::transforms::input::{ChainedInputTransform, InputTransformStep};
use botorch_core::{Normalize, Vector};
use common::{flatten, rel_err, Report};
use serde_json::Value;

/// Values: 1e-9 (relative); gradients: 1e-8.
const VAL_TOL: f64 = 1e-9;
const GRAD_TOL: f64 = 1e-8;

#[derive(Deserialize)]
struct State {
    x0: Vec<f64>,
    utility: Vec<f64>,
    likelihood_hess: Vec<Vec<f64>>,
    covar: Vec<Vec<f64>>,
    covar_chol: Vec<Vec<f64>>,
    covar_inv: Vec<Vec<f64>>,
}

#[derive(Deserialize)]
struct MllEval {
    raw: Vec<f64>,
    warm: Vec<f64>,
    value: f64,
    grad: Vec<f64>,
    #[serde(flatten)]
    state: State,
}

#[derive(Deserialize)]
struct PosteriorFx {
    x_q1: Vec<Vec<f64>>,
    mean_q1: Vec<f64>,
    var_q1: Vec<f64>,
    grad_q1: Vec<Vec<f64>>,
    x_q3: Vec<Vec<f64>>,
    mean_q3: Vec<f64>,
    cov_q3: Vec<Vec<f64>>,
    w_mean: Vec<f64>,
    w_cov: Vec<Vec<f64>>,
    grad_q3: Vec<Vec<f64>>,
    hlcov_eye: Vec<Vec<f64>>,
}

#[derive(Deserialize)]
struct FitFx {
    loss: f64,
    iterations: usize,
    attempts: usize,
    twin_datapoints: Vec<Vec<Vec<f64>>>,
    twin_losses: Vec<f64>,
    twin_attempts: Vec<usize>,
}

#[derive(Deserialize)]
struct ModelCase {
    name: String,
    likelihood: String,
    kernel: Option<Value>,
    normalize: bool,
    options: Value,
    mean_constant: f64,
    d: usize,
    datapoints: Vec<Vec<f64>>,
    comparisons: Vec<(usize, usize)>,
    draws: Vec<f64>,
    consolidated_datapoints: Vec<Vec<f64>>,
    consolidated_comparisons: Vec<(usize, usize)>,
    consolidated_indices: Vec<usize>,
    default_raw: Vec<f64>,
    bounds: Vec<(Value, Value)>,
    state: State,
    mll_evals: Vec<MllEval>,
    posterior: PosteriorFx,
    fit: Option<FitFx>,
}

fn options_of(c: &ModelCase) -> PairwiseGPOptions {
    let o = &c.options;
    let mut opts = PairwiseGPOptions {
        likelihood: if c.likelihood == "logit" {
            PairwiseLikelihood::Logit
        } else {
            PairwiseLikelihood::Probit
        },
        covar_module: c
            .kernel
            .as_ref()
            .map(|k| CovarModule::Tree(common::kernel_spec::node(k))),
        ..Default::default()
    };
    if let Some(v) = o.get("jitter") {
        opts.jitter = common::kernel_spec::num(v);
    }
    if let Some(v) = o.get("xtol") {
        opts.xtol = Some(common::kernel_spec::num(v));
    }
    if let Some(v) = o.get("maxfev") {
        opts.maxfev = Some(v.as_u64().unwrap() as usize);
    }
    if let Some(v) = o.get("consolidate_atol") {
        opts.consolidate_atol = common::kernel_spec::num(v);
    }
    if let Some(v) = o.get("consolidate_rtol") {
        opts.consolidate_rtol = common::kernel_spec::num(v);
    }
    if c.normalize {
        opts.input_transform = Some(
            ChainedInputTransform::new(vec![InputTransformStep::Normalize(Normalize::new(c.d))])
                .unwrap(),
        );
    }
    opts
}

/// The model as BoTorch's fixture built it (the mean constant set after
/// construction, followed by a warm-started `_update`).
fn build_pairwise(c: &ModelCase, x: &[Vec<f64>]) -> PairwiseGP {
    let mut m = PairwiseGP::new(
        Some((common::matrix(x), c.comparisons.clone())),
        c.d,
        options_of(c),
        Some(&c.draws),
    )
    .unwrap();
    if c.mean_constant != 0.0 {
        m.set_mean_constant(c.mean_constant);
        m.update(None).unwrap();
    }
    m
}

fn grad_err(actual: &[f64], expected: &[f64]) -> f64 {
    let scale = expected
        .iter()
        .fold(0.0f64, |m, v| m.max(v.abs()))
        .max(1e-300);
    actual
        .iter()
        .zip(expected)
        .map(|(a, e)| (a - e).abs() / scale)
        .fold(0.0, f64::max)
}

/// The 2-norm condition number of a symmetric positive definite matrix.
fn condition_number(rows: &[Vec<f64>]) -> f64 {
    let e = nalgebra::SymmetricEigen::new(common::matrix(rows)).eigenvalues;
    let (lo, hi) = e.iter().fold((f64::INFINITY, 0.0f64), |(l, h), &v| {
        (l.min(v), h.max(v.abs()))
    });
    hi / lo
}

/// The fsolve solutions are not compared: fsolve stops after a step of
/// relative size `xtol`, and where `cond(K)` is large rounding (which differs
/// between platforms, e.g. through libm) moves its iterates within that.
/// Instead botorch_rs's Newton steps from BoTorch's fsolve solution
/// (`from_bt`, [`PairwiseGP::laplace_from_solution`]) must give BoTorch's
/// utility to 1e-9: both get the same input to everything downstream of the
/// MAP solve. `covar_inv` is compared normwise to `cond(K) · eps` (the
/// accuracy of any inverse of `K`; BoTorch's `cholesky_inverse` and
/// `linalg.inv(L Lᵀ)` differ by 2.7e-7 in `probit_saturated_d1`, and its own
/// `covar_inv` on 1e-14 twins by up to 3.5e-7).
fn check_state(
    report: &mut Report,
    name: &str,
    what: &str,
    st: &LaplaceState,
    e: &State,
    from_bt: &LaplaceState,
) {
    report.check_slices(
        name,
        &format!("{what}: utility from BoTorch's fsolve solution"),
        from_bt.utility.as_slice(),
        &e.utility,
        VAL_TOL,
    );
    report.check_slices(
        name,
        &format!("{what}: utility"),
        st.utility.as_slice(),
        &e.utility,
        VAL_TOL,
    );
    for (label, actual, expected) in [
        ("likelihood_hess", &st.likelihood_hess, &e.likelihood_hess),
        ("covar", &st.covar, &e.covar),
        ("covar_chol", &st.covar_chol, &e.covar_chol),
    ] {
        report.check_slices(
            name,
            &format!("{what}: {label}"),
            &common::matrix_rows(actual),
            &flatten(expected),
            VAL_TOL,
        );
    }
    let cond = condition_number(&e.covar);
    let a = common::matrix_rows(&st.covar_inv);
    let b = flatten(&e.covar_inv);
    let scale = b.iter().fold(0.0f64, |m, v| m.max(v.abs()));
    let err = a
        .iter()
        .zip(&b)
        .fold(0.0f64, |m, (x, y)| m.max((x - y).abs()))
        / scale;
    report.check(
        name,
        &format!("{what}: covar_inv / (cond(K) eps)"),
        err / (cond * f64::EPSILON).max(VAL_TOL / f64::EPSILON * f64::EPSILON),
        1.0,
    );
}

fn bound(v: &Value) -> f64 {
    common::kernel_spec::num(v)
}

#[test]
fn pairwise_gp_matches_botorch() {
    let text = std::fs::read_to_string(fixture_path("models.json")).unwrap();
    let cases: Vec<ModelCase> = serde_json::from_str(&text).unwrap();
    let mut report = Report::default();
    for c in &cases {
        let name = c.name.as_str();
        let mut m = build_pairwise(c, &c.datapoints);
        let data = m.data().unwrap();
        // Consolidation (exact).
        let same = common::matrix_rows(&data.datapoints) == flatten(&c.consolidated_datapoints)
            && data.comparisons.pairs() == c.consolidated_comparisons.as_slice()
            && data.consolidated_indices.as_deref() == Some(c.consolidated_indices.as_slice());
        report.check(name, "consolidation", if same { 0.0 } else { 1.0 }, 0.0);
        // Parameters and bounds (exact).
        let raw_err = if m.raw_parameters() == c.default_raw.as_slice() {
            0.0
        } else {
            rel_err(m.raw_parameters(), &c.default_raw).max(f64::MIN_POSITIVE)
        };
        report.check(name, "default raw parameters", raw_err, 0.0);
        let bounds_ok = m
            .raw_parameter_bounds()
            .iter()
            .zip(&c.bounds)
            .all(|(&(lo, hi), (blo, bhi))| lo == bound(blo) && hi == bound(bhi));
        report.check(name, "bounds", if bounds_ok { 0.0 } else { 1.0 }, 0.0);
        let from_bt = m.laplace_from_solution(&c.state.x0).unwrap();
        check_state(
            &mut report,
            name,
            "construction",
            m.state().unwrap(),
            &c.state,
            &from_bt,
        );
        // MLL evaluations (each warm-started like BoTorch's).
        for (k, e) in c.mll_evals.iter().enumerate() {
            m.set_warm_start(Some(e.warm.clone()));
            let (v, g, st) = m.mll_value_and_grad(&e.raw, true).unwrap();
            let what = if k == 0 {
                "MLL (default)"
            } else {
                "MLL (random)"
            };
            report.check(
                name,
                &format!("{what} value"),
                rel_err(&[v], &[e.value]),
                VAL_TOL,
            );
            report.check(
                name,
                &format!("{what} gradient"),
                grad_err(&g.unwrap(), &e.grad),
                GRAD_TOL,
            );
            let mut at_raw = m.clone();
            at_raw.set_raw_parameters(&e.raw).unwrap();
            let from_bt = at_raw.laplace_from_solution(&e.state.x0).unwrap();
            check_state(&mut report, name, what, &st, &e.state, &from_bt);
        }
        // Posterior after the last evaluation, in eval mode.
        let last = c.mll_evals.last().unwrap();
        m.set_raw_parameters(&last.raw).unwrap();
        m.set_warm_start(Some(last.warm.clone()));
        m.set_training(true);
        m.update(None).unwrap();
        m.set_training(false);
        let p = &c.posterior;
        report.check_slices(
            name,
            "hlcov_eye",
            &common::matrix_rows(&m.state().unwrap().hlcov_eye()),
            &flatten(&p.hlcov_eye),
            VAL_TOL,
        );
        let x1 = common::matrix(&p.x_q1);
        let mut means = Vec::new();
        let mut vars = Vec::new();
        let mut grads = Vec::new();
        for i in 0..x1.nrows() {
            let xi = x1.rows(i, 1).into_owned();
            let g = m.joint_posterior_with_grad(&xi).unwrap();
            means.push(g.mean[0]);
            let v = g.covariance[(0, 0)];
            vars.push(v.max(1e-10));
            for k in 0..c.d {
                let dv = if v > 1e-10 { g.dcov[k][(0, 0)] } else { 0.0 };
                grads.push(g.dmean[k][0] + dv);
            }
        }
        report.check_slices(name, "q=1 mean", &means, &p.mean_q1, VAL_TOL);
        report.check_slices(name, "q=1 variance", &vars, &p.var_q1, VAL_TOL);
        report.check(
            name,
            "q=1 d(mean + var)/dx",
            grad_err(&grads, &flatten(&p.grad_q1)),
            GRAD_TOL,
        );
        let x3 = common::matrix(&p.x_q3);
        let g = m.joint_posterior_with_grad(&x3).unwrap();
        report.check_slices(name, "joint mean", g.mean.as_slice(), &p.mean_q3, VAL_TOL);
        report.check_slices(
            name,
            "joint covariance",
            &common::matrix_rows(&g.covariance),
            &flatten(&p.cov_q3),
            VAL_TOL,
        );
        let wm = Vector::from_vec(p.w_mean.clone());
        let wc = common::matrix(&p.w_cov);
        let gq3: Vec<f64> = (0..3 * c.d)
            .map(|j| wm.dot(&g.dmean[j]) + wc.component_mul(&g.dcov[j]).sum())
            .collect();
        report.check(
            name,
            "joint d(weighted sum)/dx",
            grad_err(&gq3, &flatten(&p.grad_q3)),
            GRAD_TOL,
        );
        // Fits from the default parameters, against BoTorch's twins.
        if let Some(f) = &c.fit {
            let mut fm = build_pairwise(c, &c.datapoints);
            let r = fm.fit(FitOptions::default()).unwrap();
            let bt: Vec<common::FitOutcome> = std::iter::once((f.loss, f.attempts))
                .chain(
                    f.twin_losses
                        .iter()
                        .copied()
                        .zip(f.twin_attempts.iter().copied()),
                )
                .collect();
            let cmp = common::compare_fits_and_first_attempts(
                &mut report,
                name,
                "fit",
                &bt,
                &[],
                (r.loss, r.attempts),
                &mut |t| {
                    let mut twin = build_pairwise(c, &f.twin_datapoints[t - 1]);
                    let rt = twin.fit(FitOptions::default()).unwrap();
                    (rt.loss, rt.attempts)
                },
            );
            let (bt_best, bt_worst) = cmp.bt_range();
            println!(
                "{name:26} fit: loss {:+.10} (BoTorch {:+.10}), iterations {} (BoTorch {}), \
                 attempts {} (BoTorch {}), stage {}: BoTorch [{bt_best:+.10}, {bt_worst:+.10}]",
                r.loss,
                f.loss,
                r.iterations,
                f.iterations,
                r.attempts,
                f.attempts,
                cmp.stage(),
            );
        }
    }
    report.finish("PairwiseGP vs BoTorch");
}

// ---------------------------------------------------------------------------
// Preference acquisition functions against BoTorch
// ---------------------------------------------------------------------------

use std::sync::Arc;

use botorch_core::acquisition::preference::{
    compose, posterior_samples_vjp, AnalyticExpectedUtilityOfBestOption,
    PairwiseBayesianActiveLearningByDisagreement, PairwiseMcPosteriorVariance,
};
use botorch_core::acquisition::{
    AcquisitionFunction, IdentityMcObjective, McAcquisitionOptions, QSimpleRegret,
};
use botorch_core::models::AffineDeterministicModel;
use botorch_core::SobolQMCNormalSampler;

#[derive(Deserialize)]
struct AcqValues {
    x: Vec<Vec<Vec<f64>>>,
    values: Vec<f64>,
    grads: Vec<Vec<Vec<f64>>>,
}

#[derive(Deserialize)]
struct WinnerFx {
    winner: Vec<Vec<f64>>,
    #[serde(flatten)]
    v: AcqValues,
}

#[derive(Deserialize)]
struct OutcomeFx {
    a: Vec<Vec<f64>>,
    b: Vec<f64>,
    #[serde(flatten)]
    v: AcqValues,
}

#[derive(Deserialize)]
struct McFx {
    pending: Option<Vec<Vec<f64>>>,
    base_samples: Vec<Vec<f64>>,
    #[serde(flatten)]
    v: AcqValues,
}

#[derive(Deserialize)]
struct BaldFx {
    eps: Vec<Vec<f64>>,
    std_noise: f64,
    #[serde(flatten)]
    v: AcqValues,
}

#[derive(Deserialize)]
struct LearnedFx {
    y: Vec<Vec<Vec<Vec<f64>>>>,
    base_samples: Vec<Vec<Vec<Vec<f64>>>>,
    values: Vec<Vec<Vec<f64>>>,
    weights: Vec<Vec<Vec<f64>>>,
    vjp: Vec<Vec<Vec<Vec<f64>>>>,
}

#[derive(Deserialize)]
struct AcqCase {
    name: String,
    eubo: AcqValues,
    eubo_winner: WinnerFx,
    eubo_outcome: OutcomeFx,
    qeubo: McFx,
    qeubo_pending: McFx,
    qeubo_outcome: McFx,
    bald: BaldFx,
    mc_variance: McFx,
    learned: LearnedFx,
}

/// Values and gradients of `acqf` at every candidate set of `fx`.
fn check_acqf(
    report: &mut Report,
    name: &str,
    label: &str,
    fx: &AcqValues,
    eval: &dyn Fn(&Matrix) -> (f64, Matrix),
) {
    let mut values = Vec::new();
    let mut grads = Vec::new();
    for x in &fx.x {
        let (v, g) = eval(&common::matrix(x));
        values.push(v);
        grads.extend(common::matrix_rows(&g));
    }
    report.check_slices(
        name,
        &format!("{label} value"),
        &values,
        &fx.values,
        VAL_TOL,
    );
    let expected: Vec<f64> = fx.grads.iter().flat_map(|m| flatten(m)).collect();
    report.check(
        name,
        &format!("{label} gradient"),
        grad_err(&grads, &expected),
        GRAD_TOL,
    );
}

#[test]
fn preference_acquisition_matches_botorch() {
    let models: Vec<ModelCase> =
        serde_json::from_str(&std::fs::read_to_string(fixture_path("models.json")).unwrap())
            .unwrap();
    let cases: Vec<AcqCase> =
        serde_json::from_str(&std::fs::read_to_string(fixture_path("acquisition.json")).unwrap())
            .unwrap();
    let mut report = Report::default();
    for c in &cases {
        let name = c.name.as_str();
        let mc = models.iter().find(|m| m.name == c.name).unwrap();
        let mut m = build_pairwise(mc, &mc.datapoints);
        m.set_training(false);
        let pref: Arc<dyn Model> = Arc::new(m);

        let eubo = AnalyticExpectedUtilityOfBestOption::new(Arc::clone(&pref), None, None).unwrap();
        check_acqf(&mut report, name, "EUBO", &c.eubo, &|x| {
            eubo.forward_with_grad(x).unwrap()
        });
        let w = Vector::from_vec(flatten(&c.eubo_winner.winner));
        let eubo_w =
            AnalyticExpectedUtilityOfBestOption::new(Arc::clone(&pref), None, Some(w)).unwrap();
        check_acqf(
            &mut report,
            name,
            "EUBO (previous winner)",
            &c.eubo_winner.v,
            &|x| eubo_w.forward_with_grad(x).unwrap(),
        );
        let om: Arc<dyn Model> = Arc::new(
            AffineDeterministicModel::new(
                common::matrix(&c.eubo_outcome.a),
                Vector::from_vec(c.eubo_outcome.b.clone()),
            )
            .unwrap(),
        );
        let eubo_o = AnalyticExpectedUtilityOfBestOption::new(
            Arc::clone(&pref),
            Some(Arc::clone(&om)),
            None,
        )
        .unwrap();
        check_acqf(
            &mut report,
            name,
            "EUBO (outcome model)",
            &c.eubo_outcome.v,
            &|x| eubo_o.forward_with_grad(x).unwrap(),
        );
        for (label, fx, outcome) in [
            ("qEUBO", &c.qeubo, None),
            ("qEUBO (pending)", &c.qeubo_pending, None),
            (
                "qEUBO (outcome model)",
                &c.qeubo_outcome,
                Some(Arc::clone(&om)),
            ),
        ] {
            let sampler = Arc::new(
                SobolQMCNormalSampler::from_base_samples(common::matrix(&fx.base_samples), None)
                    .unwrap(),
            );
            let acqf = QSimpleRegret::new(
                compose(Arc::clone(&pref), outcome).unwrap(),
                McAcquisitionOptions {
                    sampler: Some(sampler),
                    x_pending: fx.pending.as_ref().map(|p| common::matrix(p)),
                    ..Default::default()
                },
            )
            .unwrap();
            check_acqf(&mut report, name, label, &fx.v, &|x| {
                acqf.forward_with_grad(x).unwrap()
            });
        }
        let n = c.bald.eps.len();
        let bald = PairwiseBayesianActiveLearningByDisagreement::new(
            Arc::clone(&pref),
            None,
            n,
            c.bald.std_noise,
            0,
        )
        .unwrap();
        let mut values = Vec::new();
        let mut grads = Vec::new();
        for (k, x) in c.bald.v.x.iter().enumerate() {
            let eps: Vec<f64> = c.bald.eps.iter().map(|row| row[k]).collect();
            let (v, g) = bald
                .evaluate_with_draws(&common::matrix(x), &eps, true)
                .unwrap();
            values.push(v);
            grads.extend(common::matrix_rows(&g.unwrap()));
        }
        report.check_slices(name, "BALD value", &values, &c.bald.v.values, VAL_TOL);
        let expected: Vec<f64> = c.bald.v.grads.iter().flat_map(|m| flatten(m)).collect();
        report.check(name, "BALD gradient", grad_err(&grads, &expected), GRAD_TOL);
        let sampler = Arc::new(
            SobolQMCNormalSampler::from_base_samples(
                common::matrix(&c.mc_variance.base_samples),
                None,
            )
            .unwrap(),
        );
        let mcv = PairwiseMcPosteriorVariance::new(
            Arc::clone(&pref),
            Arc::new(IdentityMcObjective),
            sampler,
        )
        .unwrap();
        check_acqf(
            &mut report,
            name,
            "PairwiseMCPosteriorVariance",
            &c.mc_variance.v,
            &|x| mcv.forward_with_grad(x).unwrap(),
        );
        // LearnedObjective: N x S x 1 x q base samples shared by the t-batches.
        let l = &c.learned;
        let (s0, b, q) = (l.y.len(), l.y[0].len(), l.y[0][0].len());
        let n = l.base_samples.len();
        let mut values = Vec::new();
        let mut vjp = Vec::new();
        let mut exp_values = Vec::new();
        for s in 0..s0 {
            for bi in 0..b {
                let x = common::matrix(&l.y[s][bi]);
                let base = Matrix::from_fn(n, q, |i, p| l.base_samples[i][s][0][p]);
                let wbar = Matrix::from_fn(n, q, |i, p| l.weights[i * s0 + s][bi][p]);
                let (v, g) = posterior_samples_vjp(pref.as_ref(), &x, &base, Some(&wbar)).unwrap();
                for i in 0..n {
                    for p in 0..q {
                        values.push(v[(i, p)]);
                        exp_values.push(l.values[i * s0 + s][bi][p]);
                    }
                }
                vjp.extend(common::matrix_rows(&g.unwrap()));
            }
        }
        report.check_slices(
            name,
            "LearnedObjective samples",
            &values,
            &exp_values,
            VAL_TOL,
        );
        let expected: Vec<f64> = l
            .vjp
            .iter()
            .flat_map(|sb| sb.iter().flat_map(|m| flatten(m)))
            .collect();
        report.check(
            name,
            "LearnedObjective vjp",
            grad_err(&vjp, &expected),
            GRAD_TOL,
        );
    }
    report.finish("preference acquisition functions vs BoTorch");
}
